(3017, 'TutorialUnsocketedSupportGemInInventoryDirected', 'Hold the gem on your cursor with {0}.', 'Hold the gem on your cursor by selecting the gem and pressing <<xbox_button_a>>.', '', 73980425, '', ''),
(3018, 'TutorialSkillGemOnCursorDirected', 'Put the gem in an equipment socket with {0}.', 'Put the gem in an equipment socket by selecting the socket and pressing <<xbox_button_a>>.', '', 2445298851, '', ''),
